function findBestPathFromAmountIn(address[] memory _route, uint256 _amountIn)
    public
    view
    returns (Quote memory quote)
{
    if (_route.length < 2) {
        revert LBQuoter_InvalidLength();
    }

    quote.route = _route;

    uint256 swapLength = _route.length - 1;
    quote.pairs = new address[](swapLength);
    quote.binSteps = new uint256[](swapLength);
    quote.fees = new uint256[](swapLength);
    quote.amounts = new uint256[](_route.length);
    quote.virtualAmountsWithoutSlippage = new uint256[](_route.length);

    quote.amounts[0] = _amountIn;
    quote.virtualAmountsWithoutSlippage[0] = _amountIn;

    for (uint256 i; i < swapLength; i++) {
        // Fetch swap for V1
        quote.pairs[i] = IJoeFactory(factoryV1).getPair(_route[i], _route[i + 1]);

        if (quote.pairs[i] != address(0) && quote.amounts[i] > 0) {
            (uint256 reserveIn, uint256 reserveOut) = _getReserves(quote.pairs[i], _route[i], _route[i + 1]);

            if (reserveIn > 0 && reserveOut > 0) {
                quote.amounts[i + 1] = JoeLibrary.getAmountOut(quote.amounts[i], reserveIn, reserveOut);
                quote.virtualAmountsWithoutSlippage[i + 1] = JoeLibrary.quote(
                    (quote.virtualAmountsWithoutSlippage[i] * 997) / 1000,
                    reserveIn,
                    reserveOut
                );
                quote.fees[i] = 0.003e18; // 0.3%
            }
        }

        // Fetch swaps for V2
        ILBFactory.LBPairInformation[] memory LBPairsAvailable = ILBFactory(factoryV2).getAllLBPairs(
            IERC20(_route[i]),
            IERC20(_route[i + 1])
        );

        if (LBPairsAvailable.length > 0 && quote.amounts[i] > 0) {
            for (uint256 j; j < LBPairsAvailable.length; j++) {
                if (!LBPairsAvailable[j].ignoredForRouting) {
                    bool swapForY = address(LBPairsAvailable[j].LBPair.tokenY()) == _route[i + 1];

                    try
                        ILBRouter(routerV2).getSwapOut(LBPairsAvailable[j].LBPair, quote.amounts[i], swapForY)
                    returns (uint256 swapAmountOut, uint256 fees) {
                        if (swapAmountOut > quote.amounts[i + 1]) {
                            quote.amounts[i + 1] = swapAmountOut;
                            quote.pairs[i] = address(LBPairsAvailable[j].LBPair);
                            quote.binSteps[i] = LBPairsAvailable[j].binStep;

                            // Getting current price
                            (, , uint256 activeId) = LBPairsAvailable[j].LBPair.getReservesAndId();
                            quote.virtualAmountsWithoutSlippage[i + 1] = _getV2Quote(
                                quote.virtualAmountsWithoutSlippage[i] - fees,
                                activeId,
                                quote.binSteps[i],
                                swapForY
                            );

                            quote.fees[i] = (fees * 1e18) / quote.amounts[i]; // fee percentage in amountIn
                        }
                    } catch {}
                }
            }
        }
    }
}

function swapExactTokensForTokensSupportingFeeOnTransferTokens(
    uint256 _amountIn,
    uint256 _amountOutMin,
    uint256[] memory _pairBinSteps,
    IERC20[] memory _tokenPath,
    address _to,
    uint256 _deadline
) external override ensure(_deadline) verifyInputs(_pairBinSteps, _tokenPath) returns (uint256 amountOut) {
    address[] memory _pairs = _getPairs(_pairBinSteps, _tokenPath);

    IERC20 _targetToken = _tokenPath[_pairs.length];

    uint256 _balanceBefore = _targetToken.balanceOf(_to);

    _tokenPath[0].safeTransferFrom(msg.sender, _pairs[0], _amountIn);

    _swapSupportingFeeOnTransferTokens(_pairs, _pairBinSteps, _tokenPath, _to);

    amountOut = _targetToken.balanceOf(_to) - _balanceBefore;
    if (_amountOutMin > amountOut) revert LBRouter__InsufficientAmountOut(_amountOutMin, amountOut);
}

function swapExactAVAXForTokensSupportingFeeOnTransferTokens(
    uint256 _amountOutMin,
    uint256[] memory _pairBinSteps,
    IERC20[] memory _tokenPath,
    address _to,
    uint256 _deadline
) external payable override ensure(_deadline) verifyInputs(_pairBinSteps, _tokenPath) returns (uint256 amountOut) {
    if (_tokenPath[0] != IERC20(wavax)) revert LBRouter__InvalidTokenPath(address(_tokenPath[0]));

    address[] memory _pairs = _getPairs(_pairBinSteps, _tokenPath);

    IERC20 _targetToken = _tokenPath[_pairs.length];

    uint256 _balanceBefore = _targetToken.balanceOf(_to);

    _wavaxDepositAndTransfer(_pairs[0], msg.value);

    _swapSupportingFeeOnTransferTokens(_pairs, _pairBinSteps, _tokenPath, _to);

    amountOut = _targetToken.balanceOf(_to) - _balanceBefore;
    if (_amountOutMin > amountOut) revert LBRouter__InsufficientAmountOut(_amountOutMin, amountOut);
}

function _swapSupportingFeeOnTransferTokens(address[] memory path, address _to) internal virtual {
    for (uint256 i; i < path.length - 1; i++) {
        (address input, address output) = (path[i], path[i + 1]);
        (address token0, ) = JoeLibrary.sortTokens(input, output);
        IJoePair pair = IJoePair(JoeLibrary.pairFor(factory, input, output));
        uint256 amountInput;
        uint256 amountOutput;
        {
            // scope to avoid stack too deep errors
            (uint256 reserve0, uint256 reserve1, ) = pair.getReserves();
            (uint256 reserveInput, uint256 reserveOutput) = input == token0
                ? (reserve0, reserve1)
                : (reserve1, reserve0);
            amountInput = IERC20Joe(input).balanceOf(address(pair)).sub(reserveInput);
            amountOutput = JoeLibrary.getAmountOut(amountInput, reserveInput, reserveOutput);
        }
        (uint256 amount0Out, uint256 amount1Out) = input == token0
            ? (uint256(0), amountOutput)
            : (amountOutput, uint256(0));
        address to = i < path.length - 2 ? JoeLibrary.pairFor(factory, output, path[i + 2]) : _to;
        pair.swap(amount0Out, amount1Out, to, new bytes(0));
    }
}

function _swapSupportingFeeOnTransferTokens(
    address[] memory _pairs,
    uint256[] memory _pairBinSteps,
    IERC20[] memory _tokenPath,
    address _to
) private {
    IERC20 _token;
    uint256 _binStep;
    address _recipient;
    address _pair;

    IERC20 _tokenNext = _tokenPath[0];

    unchecked {
        for (uint256 i; i < _pairs.length; ++i) {
            _pair = _pairs[i];
            _binStep = _pairBinSteps[i];

            _token = _tokenNext;
            _tokenNext = _tokenPath[i + 1];

            _recipient = i + 1 == _pairs.length ? _to : _pairs[i + 1];

            if (_binStep == 0) {
                (uint256 _reserve0, uint256 _reserve1, ) = IJoePair(_pair).getReserves();
                if (_token < _tokenNext) {
                    uint256 _balance = _token.balanceOf(_pair);
                    uint256 _amountOut = (_reserve1 * (_balance - _reserve0) * 997) / (_balance * 1_000);

                    IJoePair(_pair).swap(0, _amountOut, _recipient, "");
                } else {
                    uint256 _balance = _token.balanceOf(_pair);
                    uint256 _amountOut = (_reserve0 * (_balance - _reserve1) * 997) / (_balance * 1_000);

                    IJoePair(_pair).swap(_amountOut, 0, _recipient, "");
                }
            } else {
                ILBPair(_pair).swap(_tokenNext == ILBPair(_pair).tokenY(), _recipient);
            }
        }
    }
}

function getAmountIn(
    uint256 amountOut,
    uint256 reserveIn,
    uint256 reserveOut
) internal pure returns (uint256 amountIn) {
    if (amountOut == 0) revert JoeLibrary__InsufficientAmount();
    if (reserveIn == 0 || reserveOut == 0) revert JoeLibrary__InsufficientLiquidity();
    uint256 numerator = reserveIn * amountOut * 1000;
    uint256 denominator = (reserveOut - amountOut) * 997;
    amountIn = numerator / denominator + 1;
}

function getAmountOut(
    uint256 amountIn,
    uint256 reserveIn,
    uint256 reserveOut
) internal pure returns (uint256 amountOut) {
    if (amountIn == 0) revert JoeLibrary__InsufficientAmount();
    if (reserveIn == 0 || reserveOut == 0) revert JoeLibrary__InsufficientLiquidity();
    uint256 amountInWithFee = amountIn * 997;
    uint256 numerator = amountInWithFee * reserveOut;
    uint256 denominator = reserveIn * 1000 + amountInWithFee;
    amountOut = numerator / denominator;
}

function swapExactTokensForAVAXSupportingFeeOnTransferTokens(
    uint256 _amountIn,
    uint256 _amountOutMinAVAX,
    uint256[] memory _pairBinSteps,
    IERC20[] memory _tokenPath,
    address payable _to,
    uint256 _deadline
) external override ensure(_deadline) verifyInputs(_pairBinSteps, _tokenPath) returns (uint256 amountOut) {
    if (_tokenPath[_pairBinSteps.length] != IERC20(wavax))
        revert LBRouter__InvalidTokenPath(address(_tokenPath[_pairBinSteps.length]));

    address[] memory _pairs = _getPairs(_pairBinSteps, _tokenPath);

    uint256 _balanceBefore = wavax.balanceOf(address(this));

    _tokenPath[0].safeTransferFrom(msg.sender, _pairs[0], _amountIn);

    _swapSupportingFeeOnTransferTokens(_pairs, _pairBinSteps, _tokenPath, address(this));

    amountOut = wavax.balanceOf(address(this)) - _balanceBefore;
    if (_amountOutMinAVAX > amountOut) revert LBRouter__InsufficientAmountOut(_amountOutMinAVAX, amountOut);

    wavax.withdraw(amountOut);
    _safeTransferAVAX(_to, amountOut);
}

